mapper.update:
UPDATE posts
title = #{title}, slug = #{slug}, summary = #{summary}, content = #{content}, cover_image = #{coverImage}, status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}, pinned = #{pinned}, published_at = #{publishedAt}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT 
FROM posts p
LEFT JOIN users u ON p.author_id = u.id
WHERE p.author_id = #{authorId}
  AND p.status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
ORDER BY p.created_at DESC

